package com.project; import java.time.LocalDateTime; import jakarta.persistence.*; @Entity @Table(name="MANAGED_CUSTOMER",uniqueConstraints=@UniqueConstraint(columnNames="CUSTOMER_ID")) public class ManagedCustomer{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="CUSTOMER_ID",nullable=false,unique=true)private Integer customerId;@Column(name="MANAGER_USERNAME",nullable=false)private String managerUsername;@Column(name="ASSIGNED_AT",nullable=false)private LocalDateTime assignedAt;@PrePersist void created(){if(assignedAt==null)assignedAt=LocalDateTime.now();}public Long getId(){return id;}public Integer getCustomerId(){return customerId;}public void setCustomerId(Integer v){customerId=v;}public String getManagerUsername(){return managerUsername;}public void setManagerUsername(String v){managerUsername=v;}}
